using System;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;

namespace LocalDictation
{
    public static class Theme
    {
        public static readonly Color Accent = Color.FromRgb(224, 91, 91);
        // Segoe Fluent Icons ships with Windows 11; Windows 10 has the same code points in Segoe MDL2 Assets.
        public static readonly FontFamily IconFont = new FontFamily("Segoe Fluent Icons, Segoe MDL2 Assets");
        public static SolidColorBrush Brush(Color c) { var b = new SolidColorBrush(c); b.Freeze(); return b; }
        public static bool IsDark(string mode) { return mode == "dark" || (mode == "system" && Convert.ToString(Microsoft.Win32.Registry.GetValue(@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize", "AppsUseLightTheme", 1)) == "0"); }
        public static void Apply(Control root, string mode)
        {
            bool dark = IsDark(mode);
            root.Resources["Bg"] = Brush(dark ? Color.FromRgb(13, 14, 17) : Color.FromRgb(247, 246, 243));
            root.Resources["Surface"] = Brush(dark ? Color.FromRgb(22, 24, 29) : Color.FromRgb(255, 254, 251));
            root.Resources["SurfaceRaised"] = Brush(dark ? Color.FromRgb(31, 34, 41) : Color.FromRgb(250, 248, 243));
            root.Resources["Hover"] = Brush(dark ? Color.FromRgb(42, 45, 54) : Color.FromRgb(239, 236, 230));
            root.Resources["Line"] = Brush(dark ? Color.FromRgb(49, 52, 62) : Color.FromRgb(224, 221, 214));
            root.Resources["Text"] = Brush(dark ? Color.FromRgb(244, 244, 246) : Color.FromRgb(34, 34, 37));
            root.Resources["Muted"] = Brush(dark ? Color.FromRgb(157, 160, 170) : Color.FromRgb(104, 104, 109));
            root.Resources["Accent"] = Brush(Accent);
            root.Resources[typeof(Button)] = Parse(@"
<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='{x:Type Button}'>
 <Setter Property='Foreground' Value='{DynamicResource Text}'/><Setter Property='Background' Value='{DynamicResource SurfaceRaised}'/><Setter Property='BorderBrush' Value='{DynamicResource Line}'/><Setter Property='BorderThickness' Value='1'/><Setter Property='Cursor' Value='Hand'/>
 <Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type Button}'><Border x:Name='Card' CornerRadius='9' Padding='{TemplateBinding Padding}' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}'><ContentPresenter HorizontalAlignment='{TemplateBinding HorizontalContentAlignment}' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='Card' Property='Background' Value='{DynamicResource Hover}'/></Trigger><Trigger Property='IsPressed' Value='True'><Setter TargetName='Card' Property='Opacity' Value='.72'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.45'/></Trigger><Trigger Property='IsKeyboardFocusWithin' Value='True'><Setter Property='BorderBrush' Value='{DynamicResource Accent}'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter>
</Style>");
            root.Resources[typeof(ComboBox)] = Parse(@"
<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='{x:Type ComboBox}'>
 <Setter Property='Foreground' Value='{DynamicResource Text}'/><Setter Property='Background' Value='{DynamicResource SurfaceRaised}'/><Setter Property='BorderBrush' Value='{DynamicResource Line}'/><Setter Property='Padding' Value='12,8'/><Setter Property='Cursor' Value='Hand'/><Setter Property='SnapsToDevicePixels' Value='True'/>
 <Setter Property='ItemContainerStyle'><Setter.Value><Style TargetType='{x:Type ComboBoxItem}'><Setter Property='Foreground' Value='{DynamicResource Text}'/><Setter Property='Background' Value='{DynamicResource SurfaceRaised}'/><Setter Property='Padding' Value='12,9'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type ComboBoxItem}'><Border x:Name='Row' CornerRadius='7' Margin='4,2' Padding='{TemplateBinding Padding}' Background='{TemplateBinding Background}'><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property='IsHighlighted' Value='True'><Setter TargetName='Row' Property='Background' Value='{DynamicResource Hover}'/></Trigger><Trigger Property='IsSelected' Value='True'><Setter TargetName='Row' Property='Background' Value='#33E05B5B'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.45'/></Trigger><Trigger Property='IsKeyboardFocusWithin' Value='True'><Setter Property='BorderBrush' Value='{DynamicResource Accent}'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style></Setter.Value></Setter>
 <Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type ComboBox}'><Grid><ToggleButton Focusable='False' IsChecked='{Binding IsDropDownOpen,RelativeSource={RelativeSource TemplatedParent},Mode=TwoWay}' Background='Transparent' BorderThickness='0'><ToggleButton.Template><ControlTemplate TargetType='ToggleButton'><ContentPresenter/></ControlTemplate></ToggleButton.Template><Border TextElement.Foreground='{TemplateBinding Foreground}' CornerRadius='9' Padding='{TemplateBinding Padding}' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='1'><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width='24'/></Grid.ColumnDefinitions><ContentPresenter Content='{TemplateBinding SelectionBoxItem}' VerticalAlignment='Center'/><Path Grid.Column='1' Data='M 2 3 L 6 7 L 10 3' Stroke='{DynamicResource Muted}' StrokeThickness='1.7' HorizontalAlignment='Center' VerticalAlignment='Center'/></Grid></Border></ToggleButton><Popup x:Name='PART_Popup' Placement='Bottom' AllowsTransparency='True' Focusable='False' IsOpen='{TemplateBinding IsDropDownOpen}' PopupAnimation='Fade'><Border Margin='0,6,0,0' MinWidth='{Binding ActualWidth,RelativeSource={RelativeSource TemplatedParent}}' MaxHeight='300' CornerRadius='10' Padding='3' Background='{DynamicResource SurfaceRaised}' BorderBrush='{DynamicResource Line}' BorderThickness='1'><ScrollViewer><ItemsPresenter/></ScrollViewer></Border></Popup></Grid><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter Property='Background' Value='{DynamicResource Hover}'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.45'/></Trigger><Trigger Property='IsKeyboardFocusWithin' Value='True'><Setter Property='BorderBrush' Value='{DynamicResource Accent}'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter>
</Style>");
            root.Resources[typeof(TextBox)] = Parse(@"
<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='{x:Type TextBox}'>
<Setter Property='Foreground' Value='{DynamicResource Text}'/><Setter Property='Background' Value='{DynamicResource Bg}'/><Setter Property='BorderBrush' Value='{DynamicResource Line}'/><Setter Property='BorderThickness' Value='1'/><Setter Property='CaretBrush' Value='{DynamicResource Text}'/><Setter Property='SelectionBrush' Value='{DynamicResource Accent}'/>
<Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type TextBox}'><Border x:Name='Box' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='7'><ScrollViewer x:Name='PART_ContentHost' Margin='0' HorizontalScrollBarVisibility='{TemplateBinding HorizontalScrollBarVisibility}' VerticalScrollBarVisibility='{TemplateBinding VerticalScrollBarVisibility}'/></Border><ControlTemplate.Triggers><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='Box' Property='BorderBrush' Value='{DynamicResource Accent}'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.45'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
            root.Resources[typeof(System.Windows.Controls.Primitives.ScrollBar)] = Parse(@"
<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='{x:Type ScrollBar}'><Setter Property='Width' Value='7'/><Setter Property='Background' Value='Transparent'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type ScrollBar}'><Track x:Name='PART_Track' Orientation='{TemplateBinding Orientation}' Minimum='{TemplateBinding Minimum}' Maximum='{TemplateBinding Maximum}' Value='{TemplateBinding Value}' ViewportSize='{TemplateBinding ViewportSize}' IsDirectionReversed='True'><Track.DecreaseRepeatButton><RepeatButton Command='ScrollBar.PageUpCommand' Opacity='0' Focusable='False'/></Track.DecreaseRepeatButton><Track.Thumb><Thumb><Thumb.Template><ControlTemplate TargetType='Thumb'><Border Background='{DynamicResource Line}' CornerRadius='4' Margin='2'/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton Command='ScrollBar.PageDownCommand' Opacity='0' Focusable='False'/></Track.IncreaseRepeatButton></Track></ControlTemplate></Setter.Value></Setter></Style>");
            root.Resources[typeof(CheckBox)] = Parse(@"
<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='{x:Type CheckBox}'><Setter Property='Foreground' Value='{DynamicResource Text}'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type CheckBox}'><StackPanel Orientation='Horizontal'><Border x:Name='Box' Width='17' Height='17' Background='{DynamicResource Bg}' BorderBrush='{DynamicResource Line}' BorderThickness='1' CornerRadius='4' VerticalAlignment='Center'><Path x:Name='Mark' Data='M 3 8 L 6 11 L 12 4' Stroke='White' StrokeThickness='2' Visibility='Collapsed'/></Border><ContentPresenter Margin='8,0,0,0' VerticalAlignment='Center'/></StackPanel><ControlTemplate.Triggers><Trigger Property='IsChecked' Value='True'><Setter TargetName='Box' Property='Background' Value='{DynamicResource Accent}'/><Setter TargetName='Mark' Property='Visibility' Value='Visible'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='Box' Property='BorderBrush' Value='{DynamicResource Accent}'/></Trigger><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='Box' Property='BorderBrush' Value='{DynamicResource Muted}'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
            root.Background = (Brush)root.Resources["Bg"];
        }
        static Style Parse(string xaml) { return (Style)XamlReader.Parse(xaml); }
    }
}
